package com.maxcape.accounthistory;

import com.google.gson.Gson;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.WorldType;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import okhttp3.OkHttpClient;

@Slf4j(topic = "maxcape.AccountHistoryPlugin")
@PluginDescriptor(
	name = "MaxCape",
	description = "Tracks skill level ups, collection log entries, boss kills, achievement diaries, and quests",
	tags = {"skill", "collection log", "tracker", "history", "boss", "diary", "quest"}
)
public class AccountHistoryPlugin extends Plugin
{
	private static final EnumSet<WorldType> ALLOWED_WORLD_TYPES = EnumSet.of(
		WorldType.MEMBERS,
		WorldType.PVP,
		WorldType.BOUNTY,
		WorldType.SKILL_TOTAL,
		WorldType.HIGH_RISK,
		WorldType.LAST_MAN_STANDING
	);

	@Inject
	private Client client;

	@Inject
	private OkHttpClient httpClient;

	@Inject
	private Gson gson;

	@Inject
	private ClientThread clientThread;

	private List<BaseTracker> trackers = Collections.emptyList();

	@Override
	protected void startUp()
	{
		trackers = List.of(
			new AccountIdentifyTracker(this, httpClient, gson),
			new LevelUpTracker(client, this, httpClient, gson),
			new CollectionLogTracker(this, httpClient, gson),
			new BossKillTracker(this, httpClient, gson),
			new DiaryTracker(client, this, httpClient, gson),
			new QuestTracker(client, this, httpClient, gson)
		);
		log.debug("MaxCape started");

		clientThread.invoke(() -> {
			GameStateChanged initialGameState = new GameStateChanged();
			initialGameState.setGameState(client.getGameState());
			trackers.forEach((tracker) -> tracker.onGameStateChanged(initialGameState));
		});
	}

	@Override
	protected void shutDown()
	{
		List<BaseTracker> toFlush = trackers;
		trackers = Collections.emptyList();
		clientThread.invoke(() -> toFlush.forEach(BaseTracker::flush));
		log.debug("MaxCape stopped");
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			trackers.forEach(BaseTracker::flush);
		}
		trackers.forEach(t -> t.onGameStateChanged(event));
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		trackers.forEach(t -> t.onStatChanged(event));
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		trackers.forEach(t -> t.onChatMessage(event));
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		trackers.forEach(t -> t.onVarbitChanged(event));
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		trackers.forEach(t -> t.onGameTick(event));
	}

	String getPlayerName()
	{
		if (client.getLocalPlayer() != null)
		{
			return client.getLocalPlayer().getName();
		}
		return null;
	}

	long getAccountHash()
	{
		return client.getAccountHash();
	}

	boolean isRestrictedWorld()
	{
		return !isAllowedWorld(client.getWorldType());
	}

	static boolean isAllowedWorld(EnumSet<WorldType> types)
	{
		return ALLOWED_WORLD_TYPES.containsAll(types);
	}

}

package com.maxcape.accounthistory;

import com.google.gson.Gson;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.events.GameTick;
import okhttp3.OkHttpClient;

import java.util.Map;

@Slf4j(topic = "maxcape.AccountIdentifyTracker")
class AccountIdentifyTracker extends BaseTracker {
	private boolean shouldSendIdentify = true;

	AccountIdentifyTracker(AccountHistoryPlugin plugin, OkHttpClient httpClient, Gson gson) {
		super(plugin, httpClient, gson);
	}

	@Override
	void onLogin() {
		log.debug("Login detected, arming identify");
		shouldSendIdentify = true;
	}

	@Override
	void onLogout() {
		log.debug("Logout detected, clearing identify flag");
		shouldSendIdentify = false;
	}

	@Override
	void onGameTick(GameTick tick) {
		if (shouldSendIdentify && plugin.getPlayerName() != null) {
			log.debug("Identifying account: {} -- {}", plugin.getPlayerName(), plugin.getAccountHash());
			sendEvent("ACCOUNT_IDENTIFY", Map.of());
			shouldSendIdentify = false;
		}
	}
}

package com.maxcape.accounthistory;

import com.google.gson.Gson;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

import java.io.IOException;
import java.time.Instant;
import java.util.LinkedHashMap;
import java.util.Map;

@Slf4j(topic = "maxcape.BaseTracker")
abstract class BaseTracker
{
	private static final String API_URL = "https://maxcape.net/api/events";
	private static final MediaType JSON = MediaType.parse("application/json");

	protected final AccountHistoryPlugin plugin;
	private final OkHttpClient httpClient;
	private final Gson gson;

	private boolean loggedIn = false;
	private boolean pendingLogin = false;

	private String lastKnownPlayerName;
	private long lastKnownAccountHash;

	BaseTracker(AccountHistoryPlugin plugin, OkHttpClient httpClient, Gson gson)
	{
		this.plugin = plugin;
		this.httpClient = httpClient;
		this.gson = gson;
	}

	protected final void sendEvent(String type, Object data)
	{
		if (plugin.isRestrictedWorld())
		{
			return;
		}
		long accountHash = plugin.getAccountHash();
		if (accountHash == 0)
		{
			accountHash = lastKnownAccountHash;
		}
		if (accountHash == 0)
		{
			log.debug("sendEvent: no account hash available, dropping {} event", type);
			return;
		}
		String playerName = plugin.getPlayerName();
		if (playerName == null)
		{
			playerName = lastKnownPlayerName;
		}
		if (playerName == null)
		{
			log.debug("sendEvent: no player name available, dropping {} event", type);
			return;
		}

		Map<String, Object> payload = new LinkedHashMap<>();
		payload.put("type", type);
		payload.put("accountHash", String.valueOf(accountHash));
		payload.put("playerName", playerName);
		payload.put("timestamp", Instant.now().toString());
		payload.put("data", data);

		String json = gson.toJson(payload);
		Request request = new Request.Builder()
			.url(API_URL)
			.post(RequestBody.create(JSON, json))
			.build();

		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Failed to send {} event: {}", type, e.getMessage());
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				response.close();
			}
		});
	}

	void flush() {}

	void onGameStateChanged(GameStateChanged event)
	{
		switch (event.getGameState())
		{
			case LOGIN_SCREEN:
			case HOPPING:
				pendingLogin = true;
				if (loggedIn)
				{
					loggedIn = false;
					onLogout();
				}
				break;
			case LOGGED_IN:
				if (pendingLogin || !loggedIn)
				{
					pendingLogin = false;
					loggedIn = true;
					onLogin();
				}
				break;
			default:
				break;
		}
	}

	protected static String stripTags(String s)
	{
		return s.replaceAll("<[^>]+>", "");
	}

	void onLogin() {}
	void onLogout() {}
	void onStatChanged(StatChanged event) {}
	void onChatMessage(ChatMessage event) {}
	void onVarbitChanged(VarbitChanged event) {}
	void onGameTick(GameTick event) {}
}

package com.maxcape.accounthistory;

import com.google.gson.Gson;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import okhttp3.OkHttpClient;

import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

@Slf4j(topic = "maxcape.BossKillTracker")
class BossKillTracker extends BaseTracker
{
	// "Your X kill/chest/completion/harvest/success/opened count is: N"
	private static final Pattern PRIMARY_PATTERN =
		Pattern.compile("Your (.+?)\\s(kill|chest|completion|harvest|success|opened)\\s?count is: ?([\\d,]+)\\.", Pattern.CASE_INSENSITIVE);
	// "Your (completed|subdued) X count is: N" — raids, Wintertodt
	private static final Pattern SECONDARY_PATTERN =
		Pattern.compile("Your (?:completed|subdued) (.+?) count is: ([\\d,]+)\\.", Pattern.CASE_INSENSITIVE);

	BossKillTracker(AccountHistoryPlugin plugin, OkHttpClient httpClient, Gson gson)
	{
		super(plugin, httpClient, gson);
	}

	@Override
	void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}

		String message = stripTags(event.getMessage());

		if (!message.contains("count is:"))
		{
			return;
		}

		String bossName = null;
		int totalKc = 0;

		Matcher m = PRIMARY_PATTERN.matcher(message);
		if (m.matches())
		{
			String rawName = m.group(1);
			String type = m.group(2);
			totalKc = parseKc(m.group(3));
			bossName = normalizeBossName(rawName, type);
		}
		else
		{
			m = SECONDARY_PATTERN.matcher(message);
			if (m.matches())
			{
				bossName = m.group(1);
				totalKc = parseKc(m.group(2));
			}
		}

		if (bossName == null)
		{
			log.debug("Kill count message did not match any pattern: '{}'", message);
			return;
		}

		log.debug("Boss kill recorded: boss='{}' totalKc={}", bossName, totalKc);
		sendEvent("BOSS_KILL", Map.of("bossName", bossName, "totalKc", totalKc));
	}

	private static int parseKc(String s)
	{
		return Integer.parseInt(s.replace(",", ""));
	}

	private static String normalizeBossName(String rawName, String type)
	{
		switch (type.toLowerCase(Locale.ROOT))
		{
			case "kill":
			case "success":
			case "opened":
				return rawName;
			case "chest":
				// Barrows chests and Lunar Chest (Perilous Moons)
				if (rawName.equals("Barrows") || rawName.contains("Lunar"))
				{
					return rawName;
				}
				return null;
			case "completion":
				if (rawName.equals("Gauntlet"))
				{
					return "Crystalline Hunllef";
				}
				if (rawName.equals("Corrupted Gauntlet"))
				{
					return "Corrupted Hunllef";
				}
				return null;
			case "harvest":
				if (rawName.equalsIgnoreCase("herbiboar"))
				{
					return "Herbiboar";
				}
				return null;
			default:
				return null;
		}
	}
}

package com.maxcape.accounthistory;

import com.google.gson.Gson;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import okhttp3.OkHttpClient;

import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

@Slf4j(topic = "maxcape.CollectionLogTracker")
class CollectionLogTracker extends BaseTracker
{
	private static final Pattern COLLECTION_LOG_PATTERN =
		Pattern.compile("New item added to your collection log: (.+)", Pattern.CASE_INSENSITIVE);

	CollectionLogTracker(AccountHistoryPlugin plugin, OkHttpClient httpClient, Gson gson)
	{
		super(plugin, httpClient, gson);
	}

	@Override
	void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}
		String message = stripTags(event.getMessage());
		Matcher matcher = COLLECTION_LOG_PATTERN.matcher(message);
		if (matcher.matches())
		{
			String itemName = matcher.group(1);
			log.debug("Collection log item: {}", itemName);
			sendEvent("COLLECTION_LOG", Map.of("itemName", itemName));
		}
	}
}

package com.maxcape.accounthistory;

import java.util.Arrays;
import java.util.Collections;
import java.util.Locale;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.runelite.api.gameval.VarbitID;

/**
 * Tier completion vars (not reward-claim vars). Karamja's original three tiers
 * use 0 = not started, 1 = started, 2 = complete.
 * Reference: https://github.com/pajlads/DinkPlugin/blob/master/src/main/java/dinkplugin/domain/AchievementDiary.java
 */
enum DiaryTier
{
	ARDOUGNE_EASY(VarbitID.ARDOUGNE_DIARY_EASY_COMPLETE, "Ardougne", "Easy", 1),
	ARDOUGNE_MEDIUM(VarbitID.ARDOUGNE_DIARY_MEDIUM_COMPLETE, "Ardougne", "Medium", 1),
	ARDOUGNE_HARD(VarbitID.ARDOUGNE_DIARY_HARD_COMPLETE, "Ardougne", "Hard", 1),
	ARDOUGNE_ELITE(VarbitID.ARDOUGNE_DIARY_ELITE_COMPLETE, "Ardougne", "Elite", 1),
	DESERT_EASY(VarbitID.DESERT_DIARY_EASY_COMPLETE, "Desert", "Easy", 1),
	DESERT_MEDIUM(VarbitID.DESERT_DIARY_MEDIUM_COMPLETE, "Desert", "Medium", 1),
	DESERT_HARD(VarbitID.DESERT_DIARY_HARD_COMPLETE, "Desert", "Hard", 1),
	DESERT_ELITE(VarbitID.DESERT_DIARY_ELITE_COMPLETE, "Desert", "Elite", 1),
	FALADOR_EASY(VarbitID.FALADOR_DIARY_EASY_COMPLETE, "Falador", "Easy", 1),
	FALADOR_MEDIUM(VarbitID.FALADOR_DIARY_MEDIUM_COMPLETE, "Falador", "Medium", 1),
	FALADOR_HARD(VarbitID.FALADOR_DIARY_HARD_COMPLETE, "Falador", "Hard", 1),
	FALADOR_ELITE(VarbitID.FALADOR_DIARY_ELITE_COMPLETE, "Falador", "Elite", 1),
	FREMENNIK_EASY(VarbitID.FREMENNIK_DIARY_EASY_COMPLETE, "Fremennik", "Easy", 1),
	FREMENNIK_MEDIUM(VarbitID.FREMENNIK_DIARY_MEDIUM_COMPLETE, "Fremennik", "Medium", 1),
	FREMENNIK_HARD(VarbitID.FREMENNIK_DIARY_HARD_COMPLETE, "Fremennik", "Hard", 1),
	FREMENNIK_ELITE(VarbitID.FREMENNIK_DIARY_ELITE_COMPLETE, "Fremennik", "Elite", 1),
	KANDARIN_EASY(VarbitID.KANDARIN_DIARY_EASY_COMPLETE, "Kandarin", "Easy", 1),
	KANDARIN_MEDIUM(VarbitID.KANDARIN_DIARY_MEDIUM_COMPLETE, "Kandarin", "Medium", 1),
	KANDARIN_HARD(VarbitID.KANDARIN_DIARY_HARD_COMPLETE, "Kandarin", "Hard", 1),
	KANDARIN_ELITE(VarbitID.KANDARIN_DIARY_ELITE_COMPLETE, "Kandarin", "Elite", 1),
	KARAMJA_EASY(VarbitID.ATJUN_EASY_DONE, "Karamja", "Easy", 2),
	KARAMJA_MEDIUM(VarbitID.ATJUN_MED_DONE, "Karamja", "Medium", 2),
	KARAMJA_HARD(VarbitID.ATJUN_HARD_DONE, "Karamja", "Hard", 2),
	KARAMJA_ELITE(VarbitID.KARAMJA_DIARY_ELITE_COMPLETE, "Karamja", "Elite", 1),
	KOUREND_EASY(VarbitID.KOUREND_DIARY_EASY_COMPLETE, "Kourend & Kebos", "Easy", 1),
	KOUREND_MEDIUM(VarbitID.KOUREND_DIARY_MEDIUM_COMPLETE, "Kourend & Kebos", "Medium", 1),
	KOUREND_HARD(VarbitID.KOUREND_DIARY_HARD_COMPLETE, "Kourend & Kebos", "Hard", 1),
	KOUREND_ELITE(VarbitID.KOUREND_DIARY_ELITE_COMPLETE, "Kourend & Kebos", "Elite", 1),
	LUMBRIDGE_EASY(VarbitID.LUMBRIDGE_DIARY_EASY_COMPLETE, "Lumbridge & Draynor", "Easy", 1),
	LUMBRIDGE_MEDIUM(VarbitID.LUMBRIDGE_DIARY_MEDIUM_COMPLETE, "Lumbridge & Draynor", "Medium", 1),
	LUMBRIDGE_HARD(VarbitID.LUMBRIDGE_DIARY_HARD_COMPLETE, "Lumbridge & Draynor", "Hard", 1),
	LUMBRIDGE_ELITE(VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE, "Lumbridge & Draynor", "Elite", 1),
	MORYTANIA_EASY(VarbitID.MORYTANIA_DIARY_EASY_COMPLETE, "Morytania", "Easy", 1),
	MORYTANIA_MEDIUM(VarbitID.MORYTANIA_DIARY_MEDIUM_COMPLETE, "Morytania", "Medium", 1),
	MORYTANIA_HARD(VarbitID.MORYTANIA_DIARY_HARD_COMPLETE, "Morytania", "Hard", 1),
	MORYTANIA_ELITE(VarbitID.MORYTANIA_DIARY_ELITE_COMPLETE, "Morytania", "Elite", 1),
	VARROCK_EASY(VarbitID.VARROCK_DIARY_EASY_COMPLETE, "Varrock", "Easy", 1),
	VARROCK_MEDIUM(VarbitID.VARROCK_DIARY_MEDIUM_COMPLETE, "Varrock", "Medium", 1),
	VARROCK_HARD(VarbitID.VARROCK_DIARY_HARD_COMPLETE, "Varrock", "Hard", 1),
	VARROCK_ELITE(VarbitID.VARROCK_DIARY_ELITE_COMPLETE, "Varrock", "Elite", 1),
	WESTERN_EASY(VarbitID.WESTERN_DIARY_EASY_COMPLETE, "Western Provinces", "Easy", 1),
	WESTERN_MEDIUM(VarbitID.WESTERN_DIARY_MEDIUM_COMPLETE, "Western Provinces", "Medium", 1),
	WESTERN_HARD(VarbitID.WESTERN_DIARY_HARD_COMPLETE, "Western Provinces", "Hard", 1),
	WESTERN_ELITE(VarbitID.WESTERN_DIARY_ELITE_COMPLETE, "Western Provinces", "Elite", 1),
	WILDERNESS_EASY(VarbitID.WILDERNESS_DIARY_EASY_COMPLETE, "Wilderness", "Easy", 1),
	WILDERNESS_MEDIUM(VarbitID.WILDERNESS_DIARY_MEDIUM_COMPLETE, "Wilderness", "Medium", 1),
	WILDERNESS_HARD(VarbitID.WILDERNESS_DIARY_HARD_COMPLETE, "Wilderness", "Hard", 1),
	WILDERNESS_ELITE(VarbitID.WILDERNESS_DIARY_ELITE_COMPLETE, "Wilderness", "Elite", 1);

	static final Map<Integer, DiaryTier> BY_VARBIT = Collections.unmodifiableMap(
		Arrays.stream(values()).collect(Collectors.toMap(tier -> tier.varbitId, Function.identity()))
	);

	final int varbitId;
	final String area;
	final String difficulty;
	private final int completionThreshold;

	DiaryTier(int varbitId, String area, String difficulty, int completionThreshold)
	{
		this.varbitId = varbitId;
		this.area = area;
		this.difficulty = difficulty;
		this.completionThreshold = completionThreshold;
	}

	boolean isComplete(int value)
	{
		return value >= completionThreshold;
	}

	static DiaryTier fromMessage(String area, String difficulty)
	{
		String normalized = area.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
		switch (normalized)
		{
			case "western":
			case "western province":
				normalized = "western provinces";
				break;
			case "kourend":
			case "kourend and kebos":
				normalized = "kourend & kebos";
				break;
			case "lumbridge":
			case "lumbridge and draynor":
				normalized = "lumbridge & draynor";
				break;
			default:
				break;
		}
		for (DiaryTier tier : values())
		{
			if (tier.area.toLowerCase(Locale.ROOT).equals(normalized)
				&& tier.difficulty.equalsIgnoreCase(difficulty))
			{
				return tier;
			}
		}
		return null;
	}
}

package com.maxcape.accounthistory;

import com.google.gson.Gson;
import java.util.EnumSet;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.VarbitChanged;
import okhttp3.OkHttpClient;

@Slf4j(topic = "maxcape.DiaryTracker")
class DiaryTracker extends BaseTracker
{
	private static final int INITIALIZATION_TICKS = 4;
	static final Pattern DIARY_PATTERN = Pattern.compile(
		"(?:Congratulations!\\s+)?You have completed all of the (?<difficulty>easy|medium|hard|elite) tasks in the (?<area>.+?) area(?=\\.|\\s|$)",
		Pattern.CASE_INSENSITIVE
	);

	private final Client client;
	// Includes the silent login baseline and live completions from either signal.
	// Never remove a tier within a session: reward updates or stale reads must not re-emit it.
	private final EnumSet<DiaryTier> completed = EnumSet.noneOf(DiaryTier.class);
	private long accountHash;
	private int initializationTicks;
	private boolean initialized;
	private boolean rescanPending;

	DiaryTracker(Client client, AccountHistoryPlugin plugin, OkHttpClient httpClient, Gson gson)
	{
		super(plugin, httpClient, gson);
		this.client = client;
	}

	@Override
	void onLogin()
	{
		reset();
	}

	@Override
	void onLogout()
	{
		reset();
	}

	private void reset()
	{
		completed.clear();
		accountHash = 0;
		initializationTicks = 0;
		initialized = false;
		rescanPending = false;
	}

	private boolean canTrack()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return false;
		}
		long currentAccount = plugin.getAccountHash();
		if (plugin.isRestrictedWorld() || currentAccount == 0 || plugin.getPlayerName() == null)
		{
			reset();
			return false;
		}
		if (accountHash != currentAccount)
		{
			reset();
			accountHash = currentAccount;
		}
		return true;
	}

	@Override
	void onGameTick(GameTick event)
	{
		if (!canTrack())
		{
			return;
		}
		if (!initialized)
		{
			if (++initializationTicks >= INITIALIZATION_TICKS)
			{
				// Merge, rather than replace, to retain messages seen during initialization.
				for (DiaryTier tier : DiaryTier.values())
				{
					if (tier.isComplete(client.getVarbitValue(tier.varbitId)))
					{
						completed.add(tier);
					}
				}
				initialized = true;
				rescanPending = false;
				log.debug("Diary baseline initialized with {} completed tiers", completed.size());
			}
			return;
		}
		if (rescanPending)
		{
			rescan();
		}
	}

	@Override
	void onVarbitChanged(VarbitChanged event)
	{
		if (client.getGameState() == GameState.LOADING)
		{
			// Preserve the session through scene loading and read settled vars next tick.
			rescanPending = initialized;
			return;
		}
		if (!canTrack() || !initialized)
		{
			return;
		}
		if (event.getVarbitId() < 0)
		{
			// A server varplayer update can contain several diary varbits.
			rescanPending = true;
			return;
		}
		DiaryTier tier = DiaryTier.BY_VARBIT.get(event.getVarbitId());
		if (tier != null && tier.isComplete(event.getValue()))
		{
			complete(tier);
		}
	}

	private void rescan()
	{
		rescanPending = false;
		for (DiaryTier tier : DiaryTier.values())
		{
			if (tier.isComplete(client.getVarbitValue(tier.varbitId)))
			{
				complete(tier);
			}
		}
	}

	@Override
	void flush()
	{
		if (canTrack() && initialized && rescanPending)
		{
			rescan();
		}
	}

	@Override
	void onChatMessage(ChatMessage event)
	{
		if ((event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.MESBOX)
			|| event.getMessage() == null || !canTrack())
		{
			return;
		}
		String message = stripTags(event.getMessage().replaceAll("(?i)<br\\s*/?>", " "))
			.replace('\u00a0', ' ').replaceAll("\\s+", " ").trim();
		Matcher matcher = DIARY_PATTERN.matcher(message);
		if (!matcher.find())
		{
			return;
		}
		DiaryTier tier = DiaryTier.fromMessage(matcher.group("area"), matcher.group("difficulty"));
		if (tier != null)
		{
			complete(tier);
		}
	}

	private void complete(DiaryTier tier)
	{
		if (!completed.add(tier))
		{
			return;
		}
		log.debug("Achievement diary completed: {} {}", tier.difficulty, tier.area);
		sendEvent("ACHIEVEMENT_DIARY", Map.of("area", tier.area, "difficulty", tier.difficulty));
	}
}

package com.maxcape.accounthistory;

import com.google.gson.Gson;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import okhttp3.OkHttpClient;

import java.util.EnumMap;
import java.util.Map;

@Slf4j(topic = "maxcape.LevelUpTracker")
class LevelUpTracker extends BaseTracker
{
	private static final int INIT_TICKS = 10;
	private static final int SKILL_COUNT = Skill.values().length;

	private final Client client;
	private final EnumMap<Skill, Integer> previousLevels = new EnumMap<>(Skill.class);

	// -1 = not started; >= 0 = counting toward next init attempt
	private int initTicksWaited = -1;
	private boolean initialized = false;

	LevelUpTracker(Client client, AccountHistoryPlugin plugin, OkHttpClient httpClient, Gson gson)
	{
		super(plugin, httpClient, gson);
		this.client = client;
	}

	@Override
	void onLogin()
	{
		log.debug("Login detected, starting level initialization");
		resetState(0);
	}

	@Override
	void onLogout()
	{
		log.debug("Logout detected, clearing level state");
		resetState(-1);
	}

	private void resetState(int initTicks)
	{
		initialized = false;
		previousLevels.clear();
		initTicksWaited = initTicks;
	}

	@Override
	void onGameTick(GameTick event)
	{
		if (initialized || initTicksWaited < 0)
		{
			return;
		}
		if (++initTicksWaited >= INIT_TICKS)
		{
			initLevels();
			initTicksWaited = 0;
		}
	}

	private void initLevels()
	{
		for (Skill skill : Skill.values())
		{
			int level = client.getRealSkillLevel(skill);
			if (level > 0)
			{
				previousLevels.put(skill, level);
			}
		}
		if (previousLevels.size() >= SKILL_COUNT)
		{
			initialized = true;
			log.debug("Level tracker initialized with {} skills", previousLevels.size());
		}
	}

	@Override
	void onStatChanged(StatChanged event)
	{
		if (!initialized)
		{
			return;
		}
		Skill skill = event.getSkill();
		int newLevel = event.getLevel();
		int oldLevel = previousLevels.getOrDefault(skill, 0);
		previousLevels.put(skill, newLevel);
		if (oldLevel > 0 && newLevel > oldLevel)
		{
			log.debug("Skill level up: {} -> {}", skill.getName(), newLevel);
			sendEvent("SKILL_LEVEL_UP", Map.of("skill", skill.getName(), "level", newLevel));
		}
	}
}

package com.maxcape.accounthistory;

import com.google.gson.Gson;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.VarbitChanged;
import okhttp3.OkHttpClient;

import java.util.EnumMap;
import java.util.Map;

@Slf4j(topic = "maxcape.QuestTracker")
class QuestTracker extends BaseTracker {
	// 500 ticks (~5 minutes) after the first varbit change before we check quest
	// states.
	// Varbits change very frequently; this avoids running getState() for every
	// quest each tick.
	private static final int CHECK_DELAY_TICKS = 500;
	private static final Quest[] QUESTS = Quest.values();

	private final Client client;
	private final EnumMap<Quest, QuestState> prevStates = new EnumMap<>(Quest.class);
	private int ticksElapsed = -1; // -1 = inactive, >=0 = ticks elapsed since armed

	QuestTracker(Client client, AccountHistoryPlugin plugin, OkHttpClient httpClient, Gson gson) {
		super(plugin, httpClient, gson);
		this.client = client;
	}

	@Override
	void onLogin() {
		log.debug("Login detected, initializing quest state");
		prevStates.clear();
		ticksElapsed = CHECK_DELAY_TICKS - 10;
	}

	@Override
	void onLogout() {
		log.debug("Logout detected, clearing quest state");
		prevStates.clear();
		ticksElapsed = -1;
	}

	@Override
	void onVarbitChanged(VarbitChanged event) {
		if (ticksElapsed < 0) {
			ticksElapsed = 0;
		}
	}

	@Override
	void onGameTick(GameTick event) {
		if (ticksElapsed >= 0 && ++ticksElapsed >= CHECK_DELAY_TICKS) {
			ticksElapsed = -1;
			checkQuestStates();
		}
	}

	@Override
	void flush() {
		if (ticksElapsed >= 0) {
			ticksElapsed = -1;
			checkQuestStates();
		}
	}

	private void checkQuestStates() {
		boolean initializing = prevStates.isEmpty();
		for (Quest quest : QUESTS) {
			QuestState curr = quest.getState(client);
			QuestState prev = prevStates.put(quest, curr);
			// prev == null on the first check after login — skip to avoid re-firing
			// events for quests already completed before this session started.
			if (prev != null && prev != QuestState.FINISHED && curr == QuestState.FINISHED) {
				log.debug("Quest completed: {}", quest.getName());
				sendEvent("QUEST_COMPLETED", Map.of("questName", quest.getName()));
			}
		}
		if (initializing) {
			log.debug("Quest state initialized with {} quests", prevStates.size());
		}
	}
}

